<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Service\Visibility\TemplateVariableVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableReadGateway;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableFilter;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableCursor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Gateway\TemplateVariableAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVariableListUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateVariableVisibilityService $visibility,
    private readonly TemplateVariableReadGateway $reader
  ) {
  }

  public function allowList(): Allow
  {
    $this->logDebug("Check allow of list usecase for Template variable");
    $span = $this->startSpan("Check allow of list usecase for Template variable");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVariableListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function count(TemplateVariableFilter $filter): int
  {
    $this->logDebug("Run list usecase for Template variable");
    $span = $this->startSpan("Run list usecase for Template variable");
    try {
      $allow = $this->allowList();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to list Template variable');
      }
      return $this->visibility->countVisibles($filter);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function list(TemplateVariableFilter $filter, ?TemplateVariableCursor $cursor = null): TemplateVariableAttributesSlide
  {
    $this->logDebug("Run list usecase for Template variable");
    $span = $this->startSpan("Run list usecase for Template variable");
    try {
      $allow = $this->allowList();
      if (!$allow->allowed) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
      }
      $slide = $this->visibility->listVisibles($filter, $cursor);
      return new TemplateVariableAttributesSlide($slide->nextCursor(), array_map( fn($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values() ));
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
